"""Generate synthetic schema-compatible NetCDF test fixtures for OCEAN-X unit tests.

IMPORTANT: These files are SYNTHETIC TEST FIXTURES.
They contain constant placeholder values (not real ocean measurements) and exist
ONLY to exercise code paths and validate schema assumptions
(dimension names, coordinate names, variable names).

They must never be presented as real scientific observations and are never
substituted for production datasets at runtime.

Regenerate with:
    cd backend && python tests/fixtures/generate_hycom_surface_fixture.py

Output (both committed to Git):
    backend/tests/fixtures/hycom_surface_fixture.nc  # mirrors processed surface schema (TIME, LAT, LON)
    backend/tests/fixtures/hycom_raw_fixture.nc      # mirrors raw HYCOM schema (TIME, DEPTH, LAT, LON)
"""

from pathlib import Path

import numpy as np
import pandas as pd
import xarray as xr

FIXTURE_DIR = Path(__file__).resolve().parent

SURFACE_FIXTURE = FIXTURE_DIR / "hycom_surface_fixture.nc"
RAW_FIXTURE = FIXTURE_DIR / "hycom_raw_fixture.nc"

# Small Bay of Bengal-like grid (region of the real dataset: 5-25N, 80-100E)
LATS = np.arange(5.0, 25.01, 1.0)
LONS = np.arange(80.0, 100.01, 1.0)

# Time range chosen to match the real dataset's coverage window (2026-09-07/08)
# so that timestamp-boundary logic (in-range vs out-of-range) can be tested.
TIMES = pd.date_range("2026-09-07T06:00:00", "2026-09-08T18:00:00", freq="6h")

# Depth levels used by the real raw HYCOM product (per backend/scripts/inspect_hycom.py
# output recorded in the project: 0, 10, 50, 100, 250, 500 m).
DEPTHS = np.array([0.0, 10.0, 50.0, 100.0, 250.0, 500.0])

# Constant, obviously-synthetic placeholder values per variable.
SYNTHETIC_VALUES = {
    "UVEL": 0.5,
    "VVEL": -0.25,
    "TEMP": 20.0,
    "SALN": 35.0,
    "SSH": 0.4,
    "TCHP": 50.0,
    "MLD": 30.0,
}

FIXTURE_ATTRS = {
    "title": "SYNTHETIC TEST FIXTURE - NOT REAL SCIENTIFIC DATA",
    "data_status": "TEST FIXTURE",
    "synthetic": "true",
    "description": "Constant placeholder values for schema/code-path testing only. "
    "Generated by backend/tests/fixtures/generate_hycom_surface_fixture.py. "
    "Never use as real ocean observations.",
}

VAR_ATTRS = {
    "UVEL": {"units": "m/s", "long_name": "SYNTHETIC fixture: eastward current"},
    "VVEL": {"units": "m/s", "long_name": "SYNTHETIC fixture: northward current"},
    "TEMP": {"units": "degC", "long_name": "SYNTHETIC fixture: temperature"},
    "SALN": {"units": "PSU", "long_name": "SYNTHETIC fixture: salinity"},
    "SSH": {"units": "m", "long_name": "SYNTHETIC fixture: sea surface height"},
    "TCHP": {"units": "KJ/cm2", "long_name": "SYNTHETIC fixture: tropical cyclone heat potential"},
    "MLD": {"units": "m", "long_name": "SYNTHETIC fixture: mixed layer depth"},
    "CURRENT_SPEED": {"units": "m/s", "long_name": "SYNTHETIC fixture: current speed"},
    "CURRENT_DIRECTION": {"units": "degrees", "long_name": "SYNTHETIC fixture: current direction"},
}


def build_data(dims):
    shape = tuple(len(d) for d in dims)
    return {name: np.full(shape, value, dtype="float32") for name, value in SYNTHETIC_VALUES.items()}


def write_surface_fixture():
    dims = (TIMES, LATS, LONS)
    data = build_data(dims)
    data["CURRENT_SPEED"] = np.sqrt(data["UVEL"] ** 2 + data["VVEL"] ** 2).astype("float32")
    direction = (np.degrees(np.arctan2(data["UVEL"], data["VVEL"])) + 360.0) % 360.0
    data["CURRENT_DIRECTION"] = direction.astype("float32")

    ds = xr.Dataset(
        data_vars={
            name: (["TIME", "LAT", "LON"], values, VAR_ATTRS[name])
            for name, values in data.items()
        },
        coords={
            "TIME": TIMES,
            "LAT": LATS,
            "LON": LONS,
            # The real processed surface file retains DEPTH as a scalar coordinate
            # (the extractor selects a single depth level), so mirror that here.
            "DEPTH": 0.0,
        },
        attrs=dict(FIXTURE_ATTRS, schema="processed surface (incois_hycom_bob_surface.nc)"),
    )
    ds.to_netcdf(
        SURFACE_FIXTURE,
        engine="netcdf4",
        encoding={name: {"zlib": True, "complevel": 9} for name in data},
    )
    print(f"wrote {SURFACE_FIXTURE} ({SURFACE_FIXTURE.stat().st_size} bytes)")


def write_raw_fixture():
    dims = (TIMES, DEPTHS, LATS, LONS)
    data = build_data(dims)
    ds = xr.Dataset(
        data_vars={
            name: (["TIME", "DEPTH", "LAT", "LON"], values, VAR_ATTRS[name])
            for name, values in data.items()
        },
        coords={"TIME": TIMES, "DEPTH": DEPTHS, "LAT": LATS, "LON": LONS},
        attrs=dict(FIXTURE_ATTRS, schema="raw HYCOM (RSMC_hycom_20260908.nc)"),
    )
    ds.to_netcdf(
        RAW_FIXTURE,
        engine="netcdf4",
        encoding={name: {"zlib": True, "complevel": 9} for name in data},
    )
    print(f"wrote {RAW_FIXTURE} ({RAW_FIXTURE.stat().st_size} bytes)")


if __name__ == "__main__":
    write_surface_fixture()
    write_raw_fixture()
    print("done - SYNTHETIC TEST FIXTURES regenerated (deterministic, constant values)")
